export default function cloudImagePath({ folder }) {
  if (typeof folder.pathDisplay !== 'string' || !folder.pathDisplay.startsWith('/')) throw new Error('Dropbox returned no folder path');
  return { path: folder.pathDisplay.replace(/\/$/, '') + '/file.png', folderPath: folder.pathDisplay };
}

