import { setTimeout as delay } from 'node:timers/promises';

export default async function confirmSavedUrl({ tag, asyncJobId, metadata, timeoutMs, pollIntervalMs }, context) {
  const started = Date.now();
  if (tag === 'complete') {
    if (metadata?.tag !== 'file') throw new Error('Dropbox did not return completed file metadata');
    return { metadata };
  }
  if (tag === 'failed') throw new Error('Dropbox could not save the URL');
  if (tag !== 'async_job_id' || typeof asyncJobId !== 'string' || !asyncJobId.trim()) throw new Error('Dropbox returned an invalid save request');
  while (Date.now() - started < timeoutMs) {
    const result = await context.actions.dropbox.save_url_check_job_status({ asyncJobId });
    if (result.tag === 'complete') {
      if (result.metadata?.tag !== 'file') throw new Error('Dropbox did not return completed file metadata');
      return { metadata: result.metadata };
    }
    if (result.tag === 'failed') throw new Error('Dropbox could not save the URL');
    if (result.tag !== 'in_progress') throw new Error('Dropbox returned an unknown job status');
    const remaining = timeoutMs - (Date.now() - started);
    if (remaining > 0) await delay(Math.min(pollIntervalMs, remaining), undefined, { signal: context.signal });
  }
  throw new Error('Dropbox save is still pending; check the job before retrying');
}
